mapper.select:
select ORG_CODE as orgCode, REGIST_BANK_CODE as registBankCode
, PBC_BANK_CODE as pbcBankCode , IS_FIN_SUB_COMPANY as isFinSubCompany , INSITITUTE_CODE as insitituteCode
,FREGIST_BANK_CODE as fregistBankCode /****查询及新建界面新增“所属银保监局”字段用于城商行附表统计时“银保监局”字段的取值*/ ,belogCodeCBRC /****查询及新建界面新增“所属银保监局”字段用于城商行附表统计时“银保监局”字段的取值*/ from CHB_ORG_REGIST_BANK_CODE where
1=1
#{orgCode,jdbcType=VARCHAR}
AND REGIST_BANK_CODE = #{registBankCode,jdbcType=VARCHAR}
#{key,jdbcType=VARCHAR}

select corbc.ORG_CODE as orgCode, corbc.REGIST_BANK_CODE as registBankCode, corbc.INSITITUTE_CODE as insitituteCode, sysi.institution_name as orgName, /****查询及新建界面新增“所属银保监局”字段用于城商行附表统计时“银保监局”字段的取值*/ corbc.belogCodeCBRC /****查询及新建界面新增“所属银保监局”字段用于城商行附表统计时“银保监局”字段的取值*/ from CHB_ORG_REGIST_BANK_CODE corbc left join sys_institution sysi on corbc.org_code=sysi.institution_code where 1=1 and corbc.status='E'
and corbc.ORG_CODE=#{orgCode,jdbcType=VARCHAR}
limit 1
